<?php foreach(array('goal'=>'Eğitim amacı','scope'=>'Eğitim kapsamı','syllabus'=>'Eğitim içeriği ve seans akışı','participation'=>'Katılım koşulları','levels'=>'Başlangıç / orta / ileri seviye uygunluğu')as$key=>$label): ?><article class="ea-coach-panel"><h2><?php echo esc_html($label); ?></h2><p><?php echo nl2br(esc_html(get_post_meta($id,'_ea_'.$key,true)?:'Bilgi henüz eklenmedi. Ayrıntılar için tesisle iletişime geçin.')); ?></p></article><?php endforeach; ?>
<article class="ea-coach-panel"><h2>Süre, günler ve eğitim türü</h2><p>Seans süresi: <strong><?php echo esc_html(get_post_meta($id,'_ea_duration',true)); ?> dakika</strong><br>Tür: <?php echo esc_html(array('individual'=>'Bireysel eğitim','group'=>'Grup eğitimi')[$type]??'Eğitim türü henüz belirtilmedi'); ?></p><p class="ea-coach-hours"><?php echo esc_html(get_post_meta($id,'_ea_hours',true)?:'Çalışma saatleri henüz tanımlanmadı.'); ?></p></article>
</section>
<?php if('group'===$type): ?><section class="ea-coach-section"><h2>Grup eğitimi ve kapasite</h2><p><?php $capacity=(int)get_post_meta($id,'_ea_group_capacity',true);echo $capacity?esc_html('Bilgilendirme amaçlı grup kapasitesi: '.$capacity.' kişi.'):'Grup kapasitesi henüz belirtilmedi; tesisle iletişime geçin.'; ?></p><p class="ea-coach-note">Mevcut sistem grup kontenjanı veya koltuk satışı yapmaz. Her eğitim zaman aralığı için tek rezervasyon kabul edilir. Grup katılım koşulları tesis tarafından teyit edilir.</p></section><?php endif; ?>
