<section class="ea-coach-section"><h2>PT paketleri</h2><div class="ea-coach-grid"><?php foreach(ea_pt_posts('ea_package')as$p)if((int)get_post_meta($p->ID,'_ea_program',true)===$id)ea_pt_package_card($p); ?></div></section>
